import { afterAll, beforeAll } from "vitest";
import { exports } from "cloudflare:workers";

// @ts-expect-error - react specific API
globalThis.IS_REACT_ACT_ENVIRONMENT = true;

// Warm up the worker module graph before tests run. The first
// exports.default.fetch() triggers Vite module resolution for
// the entire dependency tree — in CI this can take >10s if done
// inside a test, causing spurious timeouts.
beforeAll(async () => {
  await exports.default.fetch("http://warmup/");
}, 60_000);

// Give DOs a moment to finish WebSocket close handlers before
// the module is invalidated between test files.
afterAll(() => new Promise((resolve) => setTimeout(resolve, 100)));

/**
 * Global setup for React/Client integration tests.
 * Starts a miniflare worker that tests can connect to via WebSocket.
 *
 * Note: In vitest browser mode, globalSetup may be called multiple times.
 * We use port availability check to ensure only one worker is started.
 */
import { unstable_dev, type Unstable_DevWorker } from "wrangler";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { execSync } from "node:child_process";
import net from "node:net";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Fixed port for test worker - must match TEST_WORKER_PORT in vitest.config.ts
export const TEST_WORKER_PORT = 18787;

let worker: Unstable_DevWorker | undefined;
let signalHandlersInstalled = false;

// Check if port is available
function isPortAvailable(port: number): Promise<boolean> {
  return new Promise((resolve) => {
    const server = net.createServer();
    server.once("error", () => resolve(false));
    server.once("listening", () => {
      server.close();
      resolve(true);
    });
    server.listen(port, "0.0.0.0");
  });
}

async function isWorkerReachable(port: number): Promise<boolean> {
  try {
    const response = await fetch(`http://127.0.0.1:${port}`, {
      signal: AbortSignal.timeout(500)
    });
    // Any HTTP response means a worker is already serving the test port.
    return response.status >= 100;
  } catch {
    return false;
  }
}

async function waitForReachableWorker(
  port: number,
  timeoutMs: number
): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await isWorkerReachable(port)) return true;
    await new Promise((r) => setTimeout(r, 100));
  }
  return false;
}

/**
 * Kill any process listening on the given port.
 * Handles stale processes left behind by previous test runs that were
 * forcefully terminated (e.g., Ctrl+C, timeout kill) before teardown ran.
 */
function killProcessOnPort(port: number): void {
  try {
    const output = execSync(`lsof -ti tcp:${port} 2>/dev/null || true`)
      .toString()
      .trim();
    if (output) {
      const pids = output.split("\n").filter(Boolean);
      for (const pid of pids) {
        try {
          process.kill(Number(pid), "SIGKILL");
          console.log(`[setup] Killed stale process ${pid} on port ${port}`);
        } catch {
          // Process may have already exited
        }
      }
    }
  } catch {
    // lsof not available or other error — ignore
  }
}

async function stopWorker() {
  if (worker) {
    console.log("[teardown] Stopping test worker...");
    try {
      await worker.stop();
    } catch (error) {
      console.error("[teardown] Error stopping worker:", error);
      // If graceful stop fails, force-kill whatever is on our port
      killProcessOnPort(TEST_WORKER_PORT);
    }
    worker = undefined;
  }
}

export async function setup() {
  // Kill any stale processes left on the port from a previous run
  // that was forcefully terminated before teardown could run.
  const portAvailable = await isPortAvailable(TEST_WORKER_PORT);
  if (!portAvailable) {
    if (await waitForReachableWorker(TEST_WORKER_PORT, 2000)) {
      console.log(
        `[setup] Reusing test worker at http://127.0.0.1:${TEST_WORKER_PORT}`
      );
      return;
    }

    console.log(
      `[setup] Port ${TEST_WORKER_PORT} in use — killing stale process...`
    );
    killProcessOnPort(TEST_WORKER_PORT);
    // Brief wait for the OS to release the port
    await new Promise((r) => setTimeout(r, 500));
  }

  // Install signal handlers so teardown runs even on Ctrl+C / kill.
  // Only install once to avoid stacking handlers across setup calls.
  if (!signalHandlersInstalled) {
    signalHandlersInstalled = true;
    const onSignal = () => {
      stopWorker().finally(() => process.exit(1));
    };
    process.once("SIGINT", onSignal);
    process.once("SIGTERM", onSignal);
  }

  console.log("[setup] Starting test worker...");
  const testsDir = path.resolve(__dirname, "../tests");
  const workerPath = path.join(testsDir, "worker.ts");
  const configPath = path.join(testsDir, "wrangler.jsonc");

  try {
    worker = await unstable_dev(workerPath, {
      config: configPath,
      experimental: {
        disableExperimentalWarning: true
      },
      port: TEST_WORKER_PORT,
      // Bind to all interfaces so Playwright browser can access it
      ip: "0.0.0.0",
      persist: false,
      logLevel: "warn"
    });

    console.log(
      `[setup] Test worker started at http://127.0.0.1:${TEST_WORKER_PORT}`
    );
  } catch (error) {
    console.error("[setup] Failed to start test worker:", error);
    throw error;
  }
}

export async function teardown() {
  await stopWorker();
}

import {
  runQuickAction,
  type QuickActionBinding
} from "../browser/quick-actions";

declare const browser: QuickActionBinding;

// `json` requires an extract input — `prompt` / `response_format` are valid.
runQuickAction(browser, "json", {
  url: "https://example.com",
  prompt: "extract titles",
  response_format: { type: "json_schema", json_schema: {} }
});

runQuickAction(browser, "json", {
  url: "https://example.com",
  response_format: {
    type: "json_schema",
    // @ts-expect-error Browser Run requires the schema under `json_schema`
    schema: {}
  }
});

// `scrape` accepts `elements`.
runQuickAction(browser, "scrape", {
  url: "https://example.com",
  elements: [{ selector: "h1" }]
});

// `screenshot` accepts screenshot-specific options.
runQuickAction(browser, "screenshot", {
  url: "https://example.com",
  selector: "h1"
});

// A non-literal action falls back to accepting any QuickActionInput.
const action = "markdown" as
  | "markdown"
  | "content"
  | "links"
  | "snapshot"
  | "pdf";
runQuickAction(browser, action, { url: "https://example.com" });

// @ts-expect-error a page input still requires url or html
runQuickAction(browser, "markdown", {});

import { asSchema } from "ai";
import { describe, expect, it } from "vitest";
import {
  browserContent,
  browserExtract,
  browserLinks,
  browserMarkdown,
  browserScrape,
  browserScreenshot,
  browserSnapshot,
  type QuickActionBinding
} from "../browser/quick-actions";
import { createQuickActionTools } from "../browser/ai";

type Call = { action: string; params: Record<string, unknown> };

function fakeBrowser(
  handler: (action: string, params: Record<string, unknown>) => Response
): { browser: QuickActionBinding; calls: Call[] } {
  const calls: Call[] = [];
  const browser: QuickActionBinding = {
    quickAction(action: string, params: Record<string, unknown>) {
      calls.push({ action, params });
      return Promise.resolve(handler(action, params));
    }
  };
  return { browser, calls };
}

function jsonResult(result: unknown): Response {
  return new Response(JSON.stringify({ success: true, result }), {
    headers: { "content-type": "application/json" }
  });
}

type ToolExecute = (
  input: unknown,
  options: { toolCallId: string; messages: [] }
) => Promise<unknown>;

function runTool(tool: unknown, input: unknown): Promise<unknown> {
  const execute = (tool as { execute?: ToolExecute }).execute;
  if (!execute) throw new Error("tool is not executable");
  return execute(input, { toolCallId: "t", messages: [] });
}

describe("quick action helpers", () => {
  it("returns markdown and sends the url to the markdown action", async () => {
    const { browser, calls } = fakeBrowser(() =>
      jsonResult("# Example\n\nbody")
    );

    const markdown = await browserMarkdown(browser, {
      url: "https://example.com"
    });

    expect(markdown).toBe("# Example\n\nbody");
    expect(calls[0]).toEqual({
      action: "markdown",
      params: { url: "https://example.com" }
    });
  });

  it("extracts structured data via the json action", async () => {
    const { browser, calls } = fakeBrowser(() =>
      jsonResult({ products: [{ name: "Workers" }] })
    );

    const data = await browserExtract<{ products: { name: string }[] }>(
      browser,
      {
        url: "https://example.com",
        prompt: "list products",
        response_format: {
          type: "json_schema",
          json_schema: { type: "object" }
        }
      }
    );

    expect(data.products[0].name).toBe("Workers");
    expect(calls[0].action).toBe("json");
    expect(calls[0].params.prompt).toBe("list products");
  });

  it("returns links as an array", async () => {
    const { browser } = fakeBrowser(() =>
      jsonResult(["https://a.com", "https://b.com"])
    );
    const links = await browserLinks(browser, { url: "https://example.com" });
    expect(links).toEqual(["https://a.com", "https://b.com"]);
  });

  it("returns screenshot bytes with their content type", async () => {
    const { browser } = fakeBrowser(
      () =>
        new Response(new Uint8Array([137, 80, 78, 71]), {
          headers: { "content-type": "image/png" }
        })
    );

    const shot = await browserScreenshot(browser, {
      url: "https://example.com"
    });

    expect(shot.contentType).toBe("image/png");
    expect(Array.from(shot.data)).toEqual([137, 80, 78, 71]);
  });

  it("throws BrowserRenderingError on a non-ok response", async () => {
    const { browser } = fakeBrowser(
      () => new Response("nope", { status: 429 })
    );
    await expect(
      browserMarkdown(browser, { url: "https://example.com" })
    ).rejects.toMatchObject({
      name: "BrowserRenderingError",
      status: 429
    });
  });

  it("throws when the endpoint reports success: false", async () => {
    const { browser } = fakeBrowser(
      () =>
        new Response(
          JSON.stringify({
            success: false,
            errors: [{ message: "bad input" }]
          }),
          { headers: { "content-type": "application/json" } }
        )
    );
    await expect(
      browserMarkdown(browser, { url: "https://example.com" })
    ).rejects.toMatchObject({
      name: "BrowserRenderingError"
    });
  });

  it("surfaces the service's error message from a non-ok body", async () => {
    const { browser } = fakeBrowser(
      () =>
        new Response(
          JSON.stringify({
            success: false,
            errors: [{ message: "rate limited" }]
          }),
          { status: 429, headers: { "content-type": "application/json" } }
        )
    );
    await expect(
      browserMarkdown(browser, { url: "https://example.com" })
    ).rejects.toThrow(/429.*rate limited/);
  });

  it("returns scrape elements with geometry and attributes", async () => {
    const { browser, calls } = fakeBrowser(() =>
      jsonResult([
        {
          selector: "h1",
          results: [
            {
              html: "<h1>Hi</h1>",
              text: "Hi",
              width: 100,
              height: 24,
              top: 0,
              left: 0,
              attributes: [{ name: "class", value: "title" }]
            }
          ]
        }
      ])
    );

    const scraped = await browserScrape(browser, {
      url: "https://example.com",
      elements: [{ selector: "h1" }]
    });

    expect(scraped[0].selector).toBe("h1");
    expect(scraped[0].results[0].text).toBe("Hi");
    expect(scraped[0].results[0].width).toBe(100);
    expect(calls[0].params.elements).toEqual([{ selector: "h1" }]);
  });

  it("returns content and snapshot results", async () => {
    const { browser: contentBrowser } = fakeBrowser(() =>
      jsonResult("<html>body</html>")
    );
    expect(
      await browserContent(contentBrowser, { url: "https://example.com" })
    ).toBe("<html>body</html>");

    const { browser: snapBrowser } = fakeBrowser(() =>
      jsonResult({ content: "<html></html>", screenshot: "aGk=" })
    );
    const snap = await browserSnapshot(snapBrowser, {
      url: "https://example.com"
    });
    expect(snap.content).toBe("<html></html>");
    expect(snap.screenshot).toBe("aGk=");
  });
});

describe("createQuickActionTools", () => {
  it("exposes the default text tool set", () => {
    const { browser } = fakeBrowser(() => jsonResult(""));
    const tools = createQuickActionTools({ browser });
    expect(Object.keys(tools).sort()).toEqual([
      "browser_extract",
      "browser_links",
      "browser_markdown",
      "browser_scrape"
    ]);
  });

  it("honors the actions allow-list, including opt-in content", () => {
    const { browser } = fakeBrowser(() => jsonResult(""));
    const tools = createQuickActionTools({
      browser,
      actions: ["markdown", "content"]
    });
    expect(Object.keys(tools).sort()).toEqual([
      "browser_content",
      "browser_markdown"
    ]);
  });

  it("rejects stringified extraction schemas", async () => {
    const { browser } = fakeBrowser(() => jsonResult({ ok: true }));
    const tool = createQuickActionTools({ browser }).browser_extract;
    const schema = asSchema(tool.inputSchema);
    if (!schema.validate)
      throw new Error("Expected a runtime schema validator");

    expect(schema.jsonSchema).toMatchObject({
      properties: { schema: { type: "object" } }
    });

    const invalid = await schema.validate({
      url: "https://example.com",
      schema: '{"type":"object"}'
    });
    expect(invalid.success).toBe(false);
    if (invalid.success) throw new Error("Expected validation to fail");
    expect(invalid.error.message).toContain("Schema must be a JSON object");

    await expect(
      schema.validate({
        url: "https://example.com",
        schema: { type: "object" }
      })
    ).resolves.toMatchObject({ success: true });
  });

  it("truncates long markdown results to maxChars", async () => {
    const { browser } = fakeBrowser(() => jsonResult("x".repeat(100)));
    const tools = createQuickActionTools({ browser, maxChars: 10 });
    const result = (await runTool(tools.browser_markdown, {
      url: "https://example.com"
    })) as string;
    expect(result.startsWith("xxxxxxxxxx\n\n[truncated 90 characters]")).toBe(
      true
    );
  });

  it("maps the extract tool's schema onto response_format.json_schema", async () => {
    const { browser, calls } = fakeBrowser(() => jsonResult({ ok: true }));
    const tools = createQuickActionTools({ browser });
    await runTool(tools.browser_extract, {
      url: "https://example.com",
      prompt: "grab it",
      schema: { type: "object" }
    });
    expect(calls[0].action).toBe("json");
    expect(calls[0].params.response_format).toEqual({
      type: "json_schema",
      json_schema: { type: "object" }
    });
  });

  it("maps the scrape tool's selectors onto elements", async () => {
    const { browser, calls } = fakeBrowser(() => jsonResult([]));
    const tools = createQuickActionTools({ browser });
    await runTool(tools.browser_scrape, {
      url: "https://example.com",
      selectors: ["h1", ".price"]
    });
    expect(calls[0].action).toBe("scrape");
    expect(calls[0].params.elements).toEqual([
      { selector: "h1" },
      { selector: ".price" }
    ]);
  });

  it("merges host options into every request without exposing them to the model", async () => {
    const { browser, calls } = fakeBrowser(() => jsonResult("# ok"));
    const tools = createQuickActionTools({
      browser,
      options: {
        authenticate: { username: "u", password: "p" },
        gotoOptions: { waitUntil: "networkidle0" }
      }
    });
    await runTool(tools.browser_markdown, { url: "https://example.com" });
    expect(calls[0].params).toEqual({
      url: "https://example.com",
      authenticate: { username: "u", password: "p" },
      gotoOptions: { waitUntil: "networkidle0" }
    });
